zuper_api_recipe.paginate_compute_pages:
// 'compute pages' code node — runs AFTER the page-1 http fetch, BEFORE the loop. Returns the remaining page
// numbers (2..N) as objects so the loop can iterate them.
const r1 = $.getLatestNodeData('fetch page 1').data; // the http node's output ({status, data:{...}} or the raw body)
const body = (r1 && (r1.data || r1.body || r1)) || {};
const total = Number(body.total_records != null ? body.total_records : (body.total != null ? body.total : (body.total_count || 0)));
const per = 10;
const totalPages = body.total_pages != null ? Number(body.total_pages) : Math.max(1, Math.ceil(total / per));
const pages = [];
for (let p = 2; p <= totalPages; p++) pages.push({ page: p });
return { total_records: total, total_pages: totalPages, pages };

zuper_api_recipe.paginate_child_fetch:
// loop-CHILD http fetch (one iteration = one page). SAME url/filters/count as page 1, but `page` comes from the
// current loop item. json_body (EXPRESSION) value, e.g.:
{"page": "{{ $item.data.page }}", "count": 10, "filter_rules": [ /* same filters as page 1 */ ], "filter_rule_operator": "AND"}
// x-api-key header stays {{ variable.zuper_api_key }}. Do NOT compute the page with getCurrentLoopIndex arithmetic in the http field — use $item.data.page.

zuper_api_recipe.paginate_aggregate:
// 'aggregate' code node — runs AFTER the loop. Combines page-1 records with EVERY loop-page's records.
const first = (($.getLatestNodeData('fetch page 1').data||{}).data) || [];
// a loop-child node's outputs accumulate as an ARRAY across iterations:
const rest = ($.getNodeData('fetch current page')||[]).flatMap(e => ((e && e.data && (e.data.data||e.data.body&&e.data.body.data)) || []));
const all = [...first, ...rest];
const completed = all.filter(j => (j.current_job_status||{}).status_type === 'COMPLETED');
const uncompleted = all.filter(j => (j.current_job_status||{}).status_type !== 'COMPLETED');
const li = a => a.map(j => `<li>${j.work_order_number||j.job_uid}</li>`).join('');
const html = `<h3>Completed (${completed.length})</h3><ul>${li(completed)}</ul><h3>Uncompleted (${uncompleted.length})</h3><ul>${li(uncompleted)}</ul>`;
return { total: all.length, completed_count: completed.length, uncompleted_count: uncompleted.length, html };

