zuper_api_recipe.example_jobs_filter:
// SINGLE-code-node fallback that PAGINATES internally (count:10, loop pages until exhausted) — company-tz dates
const axios=require('axios'); const m=require('moment-timezone');
const tz=variable.company_timezone||'UTC';
const start_iso=m.tz(tz).startOf('day').toISOString();
const end_iso=m.tz(tz).endOf('day').toISOString();
const rules=[ { key:'scheduled_start_time', operator:'BETWEEN', value:[start_iso,end_iso], type:'default_field', module:'JOB' } ];
const per=10; let page=1, jobs=[], totalPages=1;
do {
  const r=await axios.post(`http://localhost:4500/api/jobs/filter`, { page, count:per, filter_rules:rules, filter_rule_operator:'AND' }, { headers:{ 'x-api-key': variable.zuper_api_key } });
  const b=(r.data)||{}; jobs=jobs.concat(b.data||[]);
  totalPages = b.total_pages != null ? Number(b.total_pages) : Math.ceil(Number(b.total_records||b.total||0)/per);
  page++;
} while (page <= totalPages);
const completed=jobs.filter(j=>(j.current_job_status||{}).status_type==='COMPLETED');
const uncompleted=jobs.filter(j=>(j.current_job_status||{}).status_type!=='COMPLETED');
return { ok:true, total:jobs.length, completed, uncompleted };
// NOTE: don't wrap axios in try/catch that returns {ok:false} — let a real failure THROW so the build-test loop catches it.

zuper_api_recipe.resolve_status_by_category:
// CROSS-CATEGORY status resolver — a per-JOB `code` node INSIDE a loop body that updates the status of MANY jobs
// that MAY span job categories. A `status_uid` is PER-CATEGORY, so you canNOT bake ONE uid for a multi-category set —
// resolve each job's own category's matching status_uid at RUNTIME, keyed by the CATEGORY-AGNOSTIC `status_type`
// (name as a tiebreaker/fallback). Wire it: loop --two-b--> THIS resolver --one-a--> zuper_update(UPDATE_STATUS) --loopEdge--> loop.
// GROUNDED live (GET /jobs/status/{category_uid} → { type:'success', data:{ job_statuses:[ {status_uid,status_name,status_type,...} ] } }).
const axios=require('axios');
const TARGET_TYPE='COMPLETED';   // the status_type the requirement asked for — RUNTIME enum (see status_type_enum: STARTED/CANCELED, NOT the filter enum's IN_PROGRESS/CANCELLED)
const TARGET_NAME='Completed';   // the human status name — used as a case-insensitive tiebreaker/fallback so enum drift never mis-targets
const catUid=(($item.data.job_category)||{}).category_uid;   // the CURRENT job's own category (loop iterates fetched jobs → $item.data is a job record)
if(!catUid) throw new Error('current job has no job_category.category_uid');
const r=await axios.get(`https://<dc>.zuperpro.com/api/jobs/status/${catUid}`,{headers:{'x-api-key':variable.zuper_api_key}}); // literal DC base; NEVER {{ variable }} in a URL
const statuses=(((r.data||{}).data)||{}).job_statuses||[];
let hit=statuses.find(s=>s.status_type===TARGET_TYPE);
if(!hit) hit=statuses.find(s=>String(s.status_name||'').toLowerCase()===String(TARGET_NAME).toLowerCase());
if(!hit) throw new Error(`No '${TARGET_TYPE}'/'${TARGET_NAME}' status configured in category ${catUid}`); // THROW (don't return {ok:false}) so the build-test loop catches it
return { status_uid: hit.status_uid, status_name: hit.status_name, status_type: hit.status_type, category_uid: catUid };
// The UPDATE_STATUS node then sets job_status by EXPRESSION off THIS node's output: {{ $.getLatestNodeData('<this resolver node name>').data.status_uid }}
// (operator_type=UPDATE_STATUS, source_node:'CUSTOM', module_uid: {{ $item.data.job_uid }}, job_fields:[], custom_fields:[]). NEVER a baked FIXED status_uid for a multi-category set.
// SINGLE-category / single-job status updates do NOT use this — keep the one baked status_uid there.
